use super::*;
use crate::enum_asset::EnumCommand;
const A:&str="329f41eae6ba4b4bb71dfaf60fb50001";const B:&str="329f41eae6ba4b4bb71dfaf60fb50002";const M:&str="229f41eae6ba4b4bb71dfaf60fb50001";
fn asset(id:&str)->EnumAsset{let a=EnumAsset::new(EnumAssetId::parse(id).unwrap(),"Alpha".into()).unwrap();a.prepare(EnumCommand::Add{member:EnumMemberId::parse(M).unwrap(),display_name:"First".into(),description:String::new()}).unwrap().after().clone()}
fn admit(a:&EnumAsset)->EnumAssets1025{let entries=[(A,Some("Alpha.rvnenum"))];EnumAssets1025::admit(EnumIndexInput::Table(&entries),&[("Alpha.rvnenum".into(),a.encode().unwrap().into_bytes())],true).unwrap()}
#[test] fn enum_admission1025_real_index_and_wire_bind_nominal_member(){let a=asset(A);let resources=admit(&a);assert_eq!(resources.value(a.id(),EnumMemberId::parse(M).unwrap()).unwrap(),a.value(EnumMemberId::parse(M).unwrap()).unwrap());}
#[test] fn enum_admission1025_wrong_asset_id_missing_extra_and_duplicate_files_refuse(){let entries=[(A,Some("Alpha.rvnenum"))];let files=vec![("Alpha.rvnenum".into(),asset(B).encode().unwrap().into_bytes())];assert!(EnumAssets1025::admit(EnumIndexInput::Table(&entries),&files,true).is_err());assert!(EnumAssets1025::admit(EnumIndexInput::Table(&entries),&[],true).is_err());let files=vec![files[0].clone(),files[0].clone()];assert!(EnumAssets1025::admit(EnumIndexInput::Table(&entries),&files,true).is_err());}
#[test] fn enum_admission1025_retired_or_unindexed_member_never_resolves_by_label(){let a=asset(A);let resources=admit(&a);assert!(resources.value(EnumAssetId::parse(B).unwrap(),EnumMemberId::parse(M).unwrap()).is_err());let a=a.prepare(EnumCommand::Remove(EnumMemberId::parse(M).unwrap())).unwrap().after().clone();assert!(admit(&a).value(a.id(),EnumMemberId::parse(M).unwrap()).is_err());}
#[test] fn enum_admission1025_empty_index_grants_no_type(){let resources=EnumAssets1025::admit(EnumIndexInput::Absent,&[],true).unwrap();assert!(resources.is_empty());assert!(resources.value(EnumAssetId::parse(A).unwrap(),EnumMemberId::parse(M).unwrap()).is_err());}

#[test] fn enum_admission1025_reorder_preserves_nominal_value_without_ordinal_wire(){let a=asset(A);let member=EnumMemberId::parse(M).unwrap();let value=admit(&a).value(a.id(),member).unwrap();let a=a.prepare(EnumCommand::Add{member:EnumMemberId::parse("229f41eae6ba4b4bb71dfaf60fb50002").unwrap(),display_name:"Second".into(),description:String::new()}).unwrap().after().clone();let a=a.prepare(EnumCommand::Move{member,index:1}).unwrap().after().clone();assert_eq!(admit(&a).value(a.id(),member).unwrap(),value);assert_eq!(a.ordinal(value).unwrap(),1);assert!(!serde_json::to_string(&value).unwrap().contains("ordinal"));}
